import{_ as t,o as a,c as n,a0 as i}from"./chunks/framework.DoRPXVp_.js";const h=JSON.parse('{"title":"Desktop System Tray Client Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-07-desktop-systray-client-design.md","filePath":"superpowers/specs/2026-05-07-desktop-systray-client-design.md"}'),s={name:"superpowers/specs/2026-05-07-desktop-systray-client-design.md"};function o(l,e,r,d,c,p){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="desktop-system-tray-client-design" tabindex="-1">Desktop System Tray Client Design <a class="header-anchor" href="#desktop-system-tray-client-design" aria-label="Permalink to &quot;Desktop System Tray Client Design&quot;">​</a></h1><blockquote><p>Status: Approved | 2026-05-07</p></blockquote><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Lattice is an enterprise-oriented WireGuard overlay network product that also serves individual users. Currently, end users interact with Lattice through a CLI (<code>lattice init/up/status</code>) or a Web dashboard. However:</p><ul><li>Enterprise users (developers, data analysts, product teams, external contractors) are often not comfortable with CLI tools</li><li>There is no always-visible connection status indicator — users cannot tell at a glance whether they are connected</li><li>All competitors (Tailscale, Netbird, ZeroTier, Twingate) ship desktop clients — this is table stakes for enterprise procurement</li></ul><p>A desktop system tray client closes these gaps with minimal development effort.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Deliver a lightweight cross-platform desktop system tray application that provides:</p><ol><li>Visual connection status (tray icon: grey/green/red)</li><li>Right-click menu: Connect/Disconnect, Network Details, Open Web Dashboard, Quit</li><li>Pop-up status panel showing peer count, overlay IP, TTFH, connection scenario</li><li>Auto-start on boot</li><li>Cross-platform: macOS menubar, Windows systray, Linux appindicator</li></ol><h2 id="non-goals-mvp" tabindex="-1">Non-Goals (MVP) <a class="header-anchor" href="#non-goals-mvp" aria-label="Permalink to &quot;Non-Goals (MVP)&quot;">​</a></h2><ul><li>Full settings UI (use Web dashboard)</li><li>Traffic graphs / charts</li><li>Multi-workspace switching</li><li>Dark mode settings</li><li>In-app analytics</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lattice-client/</span></span>
<span class="line"><span>├── go/                     # Wails Shell (Go)</span></span>
<span class="line"><span>│   ├── main.go             # Wails app entry</span></span>
<span class="line"><span>│   ├── systray.go          # Tray icon + menu</span></span>
<span class="line"><span>│   ├── wgstatus.go         # WireGuard status via wgctrl</span></span>
<span class="line"><span>│   └── api.go              # API calls to control plane</span></span>
<span class="line"><span>├── frontend/               # Vue 3 + Tailwind (reuses fronted/ components)</span></span>
<span class="line"><span>│   ├── index.html</span></span>
<span class="line"><span>│   ├── src/</span></span>
<span class="line"><span>│   │   ├── App.vue         # Root: empty unless panel open</span></span>
<span class="line"><span>│   │   ├── StatusPanel.vue # Pop-up status panel</span></span>
<span class="line"><span>│   │   └── main.ts</span></span>
<span class="line"><span>│   └── wails.json</span></span>
<span class="line"><span>├── wails.json              # Wails project config</span></span>
<span class="line"><span>└── Makefile</span></span></code></pre></div><h3 id="component-responsibilities" tabindex="-1">Component Responsibilities <a class="header-anchor" href="#component-responsibilities" aria-label="Permalink to &quot;Component Responsibilities&quot;">​</a></h3><p><strong>Go Shell:</strong></p><ul><li>Manage system tray lifecycle (platform-specific: macOS menubar, Windows systray, Linux appindicator)</li><li>Read local WireGuard state via <code>wgctrl</code> (reuses logic from <code>internal/agent/wireguard/</code>)</li><li>Call control plane API for peer count, workspace name (<code>GET /api/v1/...</code>)</li><li>Expose status data to Vue frontend via Wails bindings</li><li>Handle Connect/Disconnect by calling <code>lattice up/down</code> equivalent</li><li>Open Web dashboard URL in default browser</li></ul><p><strong>Vue Frontend:</strong></p><ul><li>Minimal status panel: peer count, overlay IP, TTFH, connection scenario</li><li>Reuses components from <code>fronted/src/components/ui/</code> where appropriate (button, badge, alert)</li><li>No routing — single-page panel invoked from tray</li></ul><p><strong>Build &amp; Distribution:</strong></p><ul><li>Wails builds produce platform-native binaries with embedded WebView</li><li>macOS: <code>.app</code> bundle, notarized</li><li>Windows: <code>.exe</code> with installer (NSIS)</li><li>Linux: <code>.deb</code>, <code>.rpm</code>, AppImage (reuse existing packaging pipeline)</li><li>WebView2 is system-provided on Windows (pre-installed since Win 10 1809+), WKWebView on macOS (built-in), WebKitGTK on Linux</li></ul><h2 id="technology-choice" tabindex="-1">Technology Choice <a class="header-anchor" href="#technology-choice" aria-label="Permalink to &quot;Technology Choice&quot;">​</a></h2><p><strong>Wails (Go + WebView)</strong> was chosen over alternatives:</p><table tabindex="0"><thead><tr><th>Option</th><th>Binary Size</th><th>Stack Reuse</th><th>UX</th><th>Rationale</th></tr></thead><tbody><tr><td>Wails</td><td>~12-18MB</td><td>Go + Vue 3</td><td>Native</td><td>Best fit: Go backend reuse, Vue 3 component sharing</td></tr><tr><td>Tauri</td><td>~5-10MB</td><td>Rust + Vue 3</td><td>Native</td><td>Rust is not in Lattice&#39;s tech stack</td></tr><tr><td>Electron</td><td>~50MB+</td><td>Node + Vue 3</td><td>Good</td><td>Too heavy; conflicts with &quot;lightweight&quot; positioning</td></tr><tr><td>Go + Native UI</td><td>~3MB</td><td>Go</td><td>Platform-specific</td><td>High maintenance cost for 3 platforms</td></tr></tbody></table><p>Netbird uses the same approach (Wails), providing validation of this choice in the same product category.</p><h2 id="system-tray-ux" tabindex="-1">System Tray UX <a class="header-anchor" href="#system-tray-ux" aria-label="Permalink to &quot;System Tray UX&quot;">​</a></h2><h3 id="tray-icon-states" tabindex="-1">Tray Icon States <a class="header-anchor" href="#tray-icon-states" aria-label="Permalink to &quot;Tray Icon States&quot;">​</a></h3><table tabindex="0"><thead><tr><th>State</th><th>Color</th><th>Meaning</th></tr></thead><tbody><tr><td>Disconnected</td><td>Grey</td><td>Agent not running or not enrolled</td></tr><tr><td>Connected</td><td>Green</td><td>WireGuard tunnel active, at least one peer reachable</td></tr><tr><td>Error</td><td>Red</td><td>Agent running but tunnel handshake failed</td></tr></tbody></table><h3 id="right-click-menu" tabindex="-1">Right-Click Menu <a class="header-anchor" href="#right-click-menu" aria-label="Permalink to &quot;Right-Click Menu&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Status: Connected · 10.96.0.4]</span></span>
<span class="line"><span>─────────────────────────────</span></span>
<span class="line"><span> ✓ Connected</span></span>
<span class="line"><span>   Disconnect</span></span>
<span class="line"><span>─────────────────────────────</span></span>
<span class="line"><span>   Network Details...</span></span>
<span class="line"><span>   Open Web Dashboard</span></span>
<span class="line"><span>─────────────────────────────</span></span>
<span class="line"><span>   Quit Lattice</span></span></code></pre></div><h3 id="status-panel-left-click-pop-up" tabindex="-1">Status Panel (left-click pop-up) <a class="header-anchor" href="#status-panel-left-click-pop-up" aria-label="Permalink to &quot;Status Panel (left-click pop-up)&quot;">​</a></h3><p>Compact card (300x240px) showing:</p><ul><li>Workspace name</li><li>Overlay IP</li><li>Connection scenario (LAN / NAT / Relay)</li><li>TTFH (last handshake duration)</li><li>Peer count (online / total)</li><li>Last connected time</li></ul><h2 id="binary-size" tabindex="-1">Binary Size <a class="header-anchor" href="#binary-size" aria-label="Permalink to &quot;Binary Size&quot;">​</a></h2><p>Target: 12-18MB uncompressed, 6-8MB compressed. Rationale: Tailscale is ~10MB. 12-18MB is acceptable given the additional WebView + Vue runtime overhead.</p><h2 id="integration-with-existing-code" tabindex="-1">Integration with Existing Code <a class="header-anchor" href="#integration-with-existing-code" aria-label="Permalink to &quot;Integration with Existing Code&quot;">​</a></h2><ul><li><strong>WireGuard state</strong>: Reuses <code>internal/agent/wireguard/</code> package (same <code>wgctrl</code> calls as the agent)</li><li><strong>Frontend components</strong>: Shares <code>fronted/src/components/ui/button</code>, <code>badge</code>, <code>alert</code> via path aliases</li><li><strong>API client</strong>: Reuses <code>fronted/src/api/</code> module for control plane communication</li><li><strong>Build pipeline</strong>: New <code>make build-client</code> target; CI adds Wails build step to <code>build-and-deploy</code> workflow</li><li><strong>Distribution</strong>: Adds <code>lattice-client</code> binary to existing Brew/YUM/APT/GitHub Releases pipeline</li></ul><h2 id="dependencies-risks" tabindex="-1">Dependencies &amp; Risks <a class="header-anchor" href="#dependencies-risks" aria-label="Permalink to &quot;Dependencies &amp; Risks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Mitigation</th></tr></thead><tbody><tr><td>WebView2 missing on older Windows</td><td>Detect at install, prompt user to install (one-time)</td></tr><tr><td>Linux WebKitGTK version fragmentation</td><td>AppImage bundles known-good runtime</td></tr><tr><td>macOS notarization</td><td>CI step with <code>gon</code> notary tool + Apple Developer account</td></tr><tr><td>Wails API stability</td><td>Pin Wails v2.x, test upgrades in CI before adopting</td></tr></tbody></table>`,38)])])}const g=t(s,[["render",o]]);export{h as __pageData,g as default};
